create function public.cafeline_report(p_start_date date, p_end_date date)
returns jsonb language sql security definer set search_path = public, pg_temp as $$
with bounds as (select p_start_date::timestamp at time zone 'Asia/Bishkek' as starts_at, (p_end_date + 1)::timestamp at time zone 'Asia/Bishkek' as ends_at), filtered as (select o.id,o.total_tyiyn,o.created_at from public.orders o,bounds b where o.status='completed' and o.created_at >= b.starts_at and o.created_at < b.ends_at), items as (select oi.item_name,oi.quantity,oi.line_total_tyiyn,f.created_at from public.order_items oi join filtered f on f.id=oi.order_id), summary as (select coalesce(sum(total_tyiyn),0)::integer revenue, count(*)::integer orders from filtered), products as (select item_name,sum(quantity)::integer sold,sum(line_total_tyiyn)::integer revenue from items group by item_name), days as (select (created_at at time zone 'Asia/Bishkek')::date sale_date,sum(total_tyiyn)::integer revenue from filtered group by 1)
select jsonb_build_object('revenueTyiyn',(select revenue from summary),'orderCount',(select orders from summary),'itemCount',(select coalesce(sum(quantity),0)::integer from items),'topItems',coalesce((select jsonb_agg(jsonb_build_object('name',item_name,'sold',sold,'revenueTyiyn',revenue) order by sold desc,revenue desc) from (select * from products order by sold desc,revenue desc limit 5) x),'[]'::jsonb),'items',coalesce((select jsonb_agg(jsonb_build_object('name',item_name,'sold',sold,'revenueTyiyn',revenue) order by sold desc,revenue desc) from products),'[]'::jsonb),'dailyRevenue',coalesce((select jsonb_agg(jsonb_build_object('date',sale_date::text,'revenueTyiyn',revenue) order by sale_date) from days),'[]'::jsonb));
$$;
revoke all on function public.cafeline_report(date,date) from public, anon, authenticated;
grant execute on function public.cafeline_report(date,date) to service_role;
